#include "../build_config.h"
#include "../gatelogic/FaultLog.h"

#include <string.h>

namespace gatelogic {
namespace {

/// `strlen`, stopping at `cap + 1`. Hand-rolled rather than `strnlen`, which is
/// POSIX and is not on every embedded libc this tree has to build against — and
/// a length that walks off the end of a code is the one bug a bounded length
/// exists to prevent.
size_t boundedLen(const char* code) {
  size_t len = 0U;
  while (len <= kMaxFaultCodeLen && code[len] != '\0') {
    ++len;
  }
  return len;
}

/// A code is usable when it is non-null, non-empty and fits the wire's cap.
///
/// REFUSED RATHER THAN TRUNCATED, which is the same rule `ScanAssembler` and
/// `roster::Entry` are held to: a code cut short is a DIFFERENT code, and a
/// different code is a different row in whatever the club eventually reads.
bool usable(const char* code) {
  if (code == nullptr || code[0] == '\0') {
    return false;
  }
  return boundedLen(code) <= kMaxFaultCodeLen;
}

/// Adds `by` without ever wrapping. A count that wrapped would report a board
/// that has had four billion UART errors as a healthy one, which is the same
/// reasoning as `saturatingIncrement` in GateHeartbeat.h.
uint32_t bump(uint32_t count, uint32_t by) {
  return (0xFFFFFFFFUL - count) <= by ? 0xFFFFFFFFUL : count + by;
}

} // namespace

void FaultLog::setReporting(bool on) {
  if (reporting_ == on) {
    return;
  }
  reporting_ = on;
  if (on) {
    return;
  }
  // OFF MEANS OFF, INCLUDING WHAT IS ALREADY COUNTED. See the header: a count
  // kept across a period of not reporting is a number nobody can date, and it
  // would arrive as one enormous event the moment somebody turned this back on.
  for (uint8_t i = 0U; i < kMaxFaultCodes; ++i) {
    slots_[i].used = false;
    slots_[i].count = 0U;
    slots_[i].code[0] = '\0';
    slots_[i].nextAt.disarm();
  }
  overflow_ = 0U;
  overflowNextAt_.disarm();
}

void FaultLog::setMaxPerHour(uint16_t perHour) {
  // CLAMPED HERE AS WELL AS ON THE SERVER. A zero would divide by zero in
  // windowMs() and a huge one would be a board queueing a fault per pass — and
  // the board must not depend on the server having clamped, which is the rule
  // `clampUnlockMs` was written for.
  if (perHour < kMinFaultMaxPerHour) {
    maxPerHour_ = kMinFaultMaxPerHour;
    return;
  }
  maxPerHour_ = perHour > kMaxFaultMaxPerHour ? kMaxFaultMaxPerHour : perHour;
}

int8_t FaultLog::find(const char* code) const {
  for (uint8_t i = 0U; i < kMaxFaultCodes; ++i) {
    // `kMaxFaultCodeLen + 1U`, AND THE +1 IS THE WHOLE POINT. Comparing only
    // kMaxFaultCodeLen bytes makes a 33-character code whose first 32 match a
    // tracked one the SAME code — which is truncation, wearing a comparison as
    // a disguise, in the one class whose header says a truncated code is a
    // different code. `usable()` refuses an over-long code before it gets here,
    // so nothing reaches this today; a bound that is only correct because of
    // something a caller does is a bound waiting for a second caller. The slot
    // holds kMaxFaultCodeLen + 1 bytes and both sides are NUL-terminated, so
    // reading the extra byte is defined.
    if (slots_[i].used && strncmp(slots_[i].code, code, kMaxFaultCodeLen + 1U) == 0) {
      return static_cast<int8_t>(i);
    }
  }
  return -1;
}

int8_t FaultLog::claim(uint32_t nowMs) {
  static_cast<void>(nowMs);
  for (uint8_t i = 0U; i < kMaxFaultCodes; ++i) {
    if (!slots_[i].used) {
      return static_cast<int8_t>(i);
    }
  }
  // NOTHING IS RECLAIMED, and that is what makes the window a real bound. A
  // slot is held for exactly as long as its window runs and is FREED by the
  // report at the end of it, so a code that is mid-window keeps its slot and a
  // stream of distinct codes cannot evict it to escape the rate limit.
  return -1;
}

bool FaultLog::open(int8_t at, const char* code, uint32_t nowMs) {
  Slot& slot = slots_[static_cast<uint8_t>(at)];
  const size_t len = boundedLen(code);
  if (len > kMaxFaultCodeLen) {
    return false;
  }
  memcpy(slot.code, code, len);
  slot.code[len] = '\0';
  slot.count = 0U;
  slot.used = true;
  // THE WINDOW STARTS ON THE FIRST OCCURRENCE and the event fires at the END of
  // it carrying the whole count. A fault that happened once and never again is
  // usually noise; one worth somebody's attention is still happening three
  // minutes later, and by then this says how many times.
  //
  // IT IS ALSO THE COURT BOX'S RULE, and that is not a coincidence: the two
  // boards implement one wire contract and a first occurrence that fired at
  // once here would mean a monitoring table read the same code two different
  // ways depending on which device sent it. See bridgelogic/FaultLog.
  slot.nextAt.arm(nowMs, windowMs());
  return true;
}

void FaultLog::record(const char* code, uint32_t nowMs) {
  recordMany(code, nowMs, 1U);
}

void FaultLog::recordMany(const char* code, uint32_t nowMs, uint32_t times) {
  if (!reporting_ || times == 0U || !usable(code)) {
    return;
  }

  const int8_t at = find(code);
  if (at >= 0) {
    slots_[static_cast<uint8_t>(at)].count = bump(slots_[static_cast<uint8_t>(at)].count, times);
    return;
  }

  const int8_t free = claim(nowMs);
  if (free < 0 || !open(free, code, nowMs)) {
    // THE NINTH DISTINCT CODE. Counted under its own name rather than dropped,
    // and with a counter of its own rather than one of the eight slots, so a
    // board with eight live faults can still say there were more than eight.
    if (overflow_ == 0U) {
      // The overflow counter's own window, started by its first occurrence
      // exactly as a slot's is.
      overflowNextAt_.arm(nowMs, windowMs());
    }
    overflow_ = bump(overflow_, times);
    return;
  }
  slots_[static_cast<uint8_t>(free)].count = bump(slots_[static_cast<uint8_t>(free)].count, times);
}

int8_t FaultLog::nextDue(uint32_t nowMs) const {
  // FROM ZERO, AND THAT IS ENOUGH — it did not used to be. A round-robin cursor
  // lived here to stop one chatty code taking every drain and starving the
  // seven behind it. It is dead weight under the window model: a report FREES
  // the slot it reported, so a code cannot be selected twice until it occurs
  // again and opens a fresh window, and every due code is therefore drained
  // once before any of them can repeat. The cursor is gone rather than kept as
  // a comment claiming a purpose it no longer has.
  for (uint8_t i = 0U; i < kMaxFaultCodes; ++i) {
    if (slots_[i].used && slots_[i].count > 0U && slots_[i].nextAt.expired(nowMs)) {
      return static_cast<int8_t>(i);
    }
  }
  return -1;
}

void FaultLog::emit(const char* code, uint32_t count, uint32_t nowMs, eventq::Event& out) const {
  // THE WIRE SHAPE, AND IT ADDS NO FIELD TO eventq::Event. `kind` is "fault",
  // `subject` is the CODE, `duration_ms` is the COUNT since the last report of
  // it, and `court` is the queue's sentinel, which renders as -1 — a door is
  // not on a court. `devlink::renderEventBody` is unchanged and so is Event.h.
  out.kind = eventq::Kind::Fault;
  out.court = eventq::Event::kNoCourt;
  // NONE, which `renderEventBody` writes as a literal null. A fault is not an
  // identification and pretending it had a method puts a fiction in the trail.
  out.method = eventq::Method::None;
  out.uptimeMs = nowMs;
  out.durationMs = count;
  static_cast<void>(out.setSubject(code));
}

bool FaultLog::drain(uint32_t nowMs, eventq::Event& out) {
  if (!reporting_) {
    return false;
  }

  const int8_t at = nextDue(nowMs);
  if (at >= 0) {
    Slot& slot = slots_[static_cast<uint8_t>(at)];
    emit(slot.code, slot.count, nowMs, out);
    // THE SLOT IS FREED BY ITS OWN REPORT. The next occurrence of this code
    // opens a fresh slot and a fresh window, so two events of one code are
    // always at least a window apart and a code that has stopped stops holding
    // one of the eight.
    slot.used = false;
    slot.count = 0U;
    slot.code[0] = '\0';
    slot.nextAt.disarm();
    return true;
  }

  // THE OVERFLOW COUNTER, LAST, because a named code is worth more to whoever
  // reads this than "there were others". It keeps its own window for the same
  // reason every code does.
  if (overflow_ > 0U && overflowNextAt_.expired(nowMs)) {
    emit(kFaultOverflow, overflow_, nowMs, out);
    overflow_ = 0U;
    overflowNextAt_.disarm();
    return true;
  }
  return false;
}

uint8_t FaultLog::tracked() const {
  uint8_t used = 0U;
  for (uint8_t i = 0U; i < kMaxFaultCodes; ++i) {
    if (slots_[i].used) {
      ++used;
    }
  }
  return used;
}

uint32_t FaultLog::pending(const char* code) const {
  if (!usable(code)) {
    return 0U;
  }
  const int8_t at = find(code);
  return at < 0 ? 0U : slots_[static_cast<uint8_t>(at)].count;
}

} // namespace gatelogic
